import sys

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def max_primes(sequence):
    prefix_sums = []
    current_sum = 0
    for num in sequence:
        current_sum += num
        prefix_sums.append(current_sum)
    return sum(1 for sum_val in prefix_sums if is_prime(sum_val))

